function exerciseRows(exercises){return exercises.map(e=>i18n`<div class="exercise-row"><div class="exercise-art">${icon('dumbbell')}</div><div class="exercise-info"><strong>${esc(e.name)}</strong><span>${esc(labels[e.muscle_group])} <span aria-hidden="true">·</span> ${e.target_sets} set × ${e.target_rep_min}–${e.target_rep_max} rep</span></div><span class="small muted">${e.target_weight_kg===null?i18n('Beban ringan'):e.target_weight_kg+' kg'}</span><button class="exercise-detail" data-exercise="${e.exercise_id}" aria-label="Butiran ${esc(e.name)}">${icon('chevron')}</button></div>`).join('');}
function bindExercises(){$$('[data-exercise]').forEach(b=>b.onclick=async()=>{try{const {exercise:e,alternatives}=await api('/exercises/'+b.dataset.exercise+'/alternatives');modal(esc(e.name),i18n`${e.image_url?i18n`<img src="${esc(e.image_url)}" alt="Demonstrasi ${esc(e.name)}" style="width:100%;max-height:260px;object-fit:contain">`:''}<div class="row wrap"><span class="badge">${labels[e.muscle_group]}</span><span class="badge gray">${labels[e.equipment_type]}</span><span class="badge gray">${labels[e.level]}</span></div><p style="margin-top:20px">${esc(systemText(e.instructions))}</p><h3>Senaman alternatif</h3>${alternatives.length?alternatives.map(a=>`<div class="list-item"><strong class="small">${esc(a.name)}</strong><p>${esc(systemText(a.instructions))}</p></div>`).join(''):i18n('<p class="muted small">Tiada alternatif sepadan dengan peralatan, tahap dan limitasi kamu.</p>')}`);}catch(e){toast(e.message);}});}
